{
  "schemaVersion": "0.2",
  "slug": "notification",
  "name": "Notification",
  "family": "E",
  "status": "experimental",
  "purpose": "Presents a persistent notification card with title, message, and dismiss control.",
  "scenarios": [
    "Show a sync completion notice",
    "Display a permission request",
    "Present a system warning"
  ],
  "props": {
    "title": {
      "type": "string",
      "required": true,
      "description": "Notification headline."
    },
    "message": {
      "type": "string",
      "required": true,
      "description": "Notification body text."
    },
    "variant": {
      "type": "enum",
      "required": false,
      "description": "Semantic tone.",
      "values": [
        "info",
        "success",
        "warning",
        "error"
      ],
      "default": "info"
    },
    "onDismiss": {
      "type": "event",
      "required": false,
      "description": "Called when the dismiss control is activated."
    },
    "dismissLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the dismiss control."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "variant",
      "values": [
        "info",
        "success",
        "warning",
        "error"
      ],
      "default": "info",
      "description": "Semantic tone."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Visible notification."
    },
    {
      "name": "dismissed",
      "description": "Dismissed by the user."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "button",
      "link"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a persistent notification for transient feedback; use Toast.",
    "Do not stack more than three notifications at once."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [
      "Escape dismisses when the notification has focus"
    ],
    "focus": "Dismiss control is a button in tab order.",
    "labeling": "Title labels the notification; icon is decorative with text tone.",
    "wcag": [
      "1.3.1",
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Full width on compact; fixed measure on larger breakpoints.",
    "breakpoints": {
      "compact": "Full width card.",
      "medium": "Constrained width.",
      "large": "Constrained width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "notification",
    "states": [
      "default",
      "dismissed",
      "info",
      "success",
      "warning",
      "error"
    ],
    "intents": [
      "notify-status"
    ]
  }
}

import './styles.css'

export interface NotificationProps {
  title: string
  message: string
  variant?: 'info' | 'success' | 'warning' | 'error'
  onDismiss?: () => void
  dismissLabel?: string
  className?: string
}

export function Notification({
  title,
  message,
  variant = 'info',
  onDismiss,
  dismissLabel = 'Dismiss',
  className,
}: NotificationProps) {
  const classes = ['cu-notification', 'cu-notification--' + variant, className].filter(Boolean).join(' ')
  return (
    <div className={classes} role="status" data-ai-role="notification" data-ai-intent="notify-status" data-ai-state={variant}>
      <div className="cu-notification__body">
        <p className="cu-notification__title">{title}</p>
        <p className="cu-notification__message">{message}</p>
      </div>
      {onDismiss ? (
        <button type="button" className="cu-notification__dismiss" aria-label={dismissLabel} onClick={onDismiss}>
          ×
        </button>
      ) : null}
    </div>
  )
}

.cu-notification {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-inline-start-width: 4px;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
}

.cu-notification--info {
  border-inline-start-color: var(--cu-color-palette-brand);
}

.cu-notification--success {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, green);
}

.cu-notification--warning {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, orange);
}

.cu-notification--error {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, red);
}

.cu-notification__title {
  margin: 0;
  font-weight: 600;
}

.cu-notification__message {
  margin: var(--cu-space-1) 0 0;
}

.cu-notification__dismiss {
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-notification__dismiss:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}
